using Bunit;using Harborline.UIAdapters.Blazor.Components.AI;using Xunit;
namespace Harborline.UIAdapters.Blazor.Tests;
public sealed class ChatPerformanceTests:BunitContext{public ChatPerformanceTests(){var module=JSInterop.SetupModule("./_content/Harborline.UIAdapters.Blazor/chat.js");module.SetupVoid("scrollLogToEnd",_=>true).SetVoidResult();module.SetupVoid("focusMessage",_=>true).SetVoidResult();module.Setup<bool>("isNearEnd",_=>true).SetResult(true);}[Fact]public void TwoHundredFiftySixMessagesAndNinetySixReplacementsStayExact(){var user=new ChatParticipant("Ada");var cut=Render<HarborlineChat>(p=>p.Add(x=>x.User,user).Add(x=>x.Messages,Messages(0,user)));for(var cycle=0;cycle<96;cycle++){cut.Render(p=>p.Add(x=>x.User,user).Add(x=>x.Messages,Messages(cycle,user)));Assert.Equal(256,cut.FindAll("article").Count);Assert.Equal($"{cycle}-255",cut.FindAll("article")[255].GetAttribute("data-hl-message-id"));}}private static ChatMessage[] Messages(int cycle,ChatParticipant user)=>Enumerable.Range(0,256).Select(i=>new ChatMessage($"{cycle}-{i}",user,i%2==0?ChatMessageRole.User:ChatMessageRole.Assistant,$"Message {i}")).ToArray();}
